local AnvilHardyMaker = {}
local PRODUCTS = {
    iron_anvilhardy = { name = "Železni trdi nastavek za nakovalo", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni trdi nastavek za nakovalo za kovace." },
    bronze_anvilhardy = { name = "Bronast trdi nastavek za nakovalo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast trdi nastavek za nakovalo za kovace." },
    silver_anvilhardy = { name = "Srebrn trdi nastavek za nakovalo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn trdi nastavek za nakovalo za kovace." },
    gilded_anvilhardy = { name = "Pozlačen trdi nastavek za nakovalo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen trdi nastavek za nakovalo za kovace." },
    jewel_set_anvilhardy = { name = "Draguljast trdi nastavek za nakovalo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast trdi nastavek za nakovalo za kovace." },
    royal_sovereign_anvilhardy = { name = "Kraljevski suveren trdi nastavek za nakovalo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren trdi nastavek za nakovalo z biseri za krono." },
}
local BUILDINGS = {
    anvilhardy_workshop = { name = "Anvilhardy delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    anvilhardy_house = { name = "Anvilhardy hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_anvilhardy_atelier = { name = "Mojstrski anvilhardy atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_anvilhardy_palace = { name = "Suverena anvilhardy palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
AnvilHardyMaker.ironStock=18; AnvilHardyMaker.bronzeStock=14; AnvilHardyMaker.woodStock=10; AnvilHardyMaker.leatherStock=8; AnvilHardyMaker.silverStock=8; AnvilHardyMaker.goldStock=6; AnvilHardyMaker.jewelStock=4; AnvilHardyMaker.pearlStock=4
AnvilHardyMaker.productStock = {}; AnvilHardyMaker.buildings = {}; AnvilHardyMaker.maker = nil; AnvilHardyMaker.activeMaking = {}; AnvilHardyMaker.totalProducts = 0; AnvilHardyMaker.dayTimer = 0
function AnvilHardyMaker.init() AnvilHardyMaker.ironStock=18; AnvilHardyMaker.bronzeStock=14; AnvilHardyMaker.woodStock=10; AnvilHardyMaker.leatherStock=8; AnvilHardyMaker.silverStock=8; AnvilHardyMaker.goldStock=6; AnvilHardyMaker.jewelStock=4; AnvilHardyMaker.pearlStock=4; AnvilHardyMaker.productStock={}; AnvilHardyMaker.buildings={}; AnvilHardyMaker.maker=nil; AnvilHardyMaker.activeMaking={}; AnvilHardyMaker.totalProducts=0; AnvilHardyMaker.dayTimer=0; print("[AnvilHardyMaker] Royal Anvil Hardy Maker System initialized (6 products, 4 buildings)") end
function AnvilHardyMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AnvilHardyMaker.maker={name=n or ("Nastavkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nastavkar najet: %s (spretnost: %d)",AnvilHardyMaker.maker.name,s),"success") end; return true end
function AnvilHardyMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AnvilHardyMaker.build(id) local ok,e=AnvilHardyMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AnvilHardyMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AnvilHardyMaker.getQualityBonus() local b=0; for _,bd in ipairs(AnvilHardyMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AnvilHardyMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and AnvilHardyMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and AnvilHardyMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and AnvilHardyMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and AnvilHardyMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and AnvilHardyMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AnvilHardyMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AnvilHardyMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AnvilHardyMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AnvilHardyMaker.buildings==0 then return false,"Potrebna nastavkarska delavnica" end; if not AnvilHardyMaker.maker then return false,"Potreben nastavkar" end; return true end
function AnvilHardyMaker.make(pt,qty) qty=qty or 1; local ok,e=AnvilHardyMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then AnvilHardyMaker.ironStock=AnvilHardyMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then AnvilHardyMaker.bronzeStock=AnvilHardyMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then AnvilHardyMaker.woodStock=AnvilHardyMaker.woodStock-d.woodCost*qty end; if d.leatherCost then AnvilHardyMaker.leatherStock=AnvilHardyMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then AnvilHardyMaker.silverStock=AnvilHardyMaker.silverStock-d.silverCost*qty end; if d.goldCost then AnvilHardyMaker.goldStock=AnvilHardyMaker.goldStock-d.goldCost*qty end; if d.jewelCost then AnvilHardyMaker.jewelStock=AnvilHardyMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then AnvilHardyMaker.pearlStock=AnvilHardyMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if AnvilHardyMaker.maker then t=math.max(1,t-math.floor(AnvilHardyMaker.maker.skill/13)) end; table.insert(AnvilHardyMaker.activeMaking,{id="anvilhardy_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AnvilHardyMaker.completeMaking(m) local q=1.0+(AnvilHardyMaker.getQualityBonus()/100); if AnvilHardyMaker.maker then q=q+(AnvilHardyMaker.maker.skill/140) end; q=math.min(2.5,q); AnvilHardyMaker.productStock[m.productType]=(AnvilHardyMaker.productStock[m.productType] or 0)+m.quantity; AnvilHardyMaker.totalProducts=AnvilHardyMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AnvilHardyMaker.maker then AnvilHardyMaker.maker.itemsMade=AnvilHardyMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then AnvilHardyMaker.maker.skill=math.min(100,AnvilHardyMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nastavek izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"anvilhardy.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function AnvilHardyMaker.update(dt) if not _G.state then return end; AnvilHardyMaker.dayTimer=AnvilHardyMaker.dayTimer+dt; if AnvilHardyMaker.dayTimer>=30 then AnvilHardyMaker.dayTimer=0; for i=#AnvilHardyMaker.activeMaking,1,-1 do local m=AnvilHardyMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AnvilHardyMaker.completeMaking(m); table.remove(AnvilHardyMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AnvilHardyMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AnvilHardyMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AnvilHardyMaker.getStats() return {ironStock=AnvilHardyMaker.ironStock,bronzeStock=AnvilHardyMaker.bronzeStock,woodStock=AnvilHardyMaker.woodStock,leatherStock=AnvilHardyMaker.leatherStock,silverStock=AnvilHardyMaker.silverStock,goldStock=AnvilHardyMaker.goldStock,jewelStock=AnvilHardyMaker.jewelStock,pearlStock=AnvilHardyMaker.pearlStock,productStock=AnvilHardyMaker.productStock,numBuildings=#AnvilHardyMaker.buildings,hasMaker=AnvilHardyMaker.maker~=nil,makerName=AnvilHardyMaker.maker and AnvilHardyMaker.maker.name or "—",makerSkill=AnvilHardyMaker.maker and AnvilHardyMaker.maker.skill or 0,activeMaking=#AnvilHardyMaker.activeMaking,totalProducts=AnvilHardyMaker.totalProducts} end
return AnvilHardyMaker
